    'leaders update training_sessions|UPDATE', '((department_id = my_department_id()) AND is_training_manager() AND (done IS NOT TRUE))|((department_id = my_department_id()) AND is_training_manager())',
    'leaders write training_sessions|INSERT', '|((department_id = my_department_id()) AND is_training_manager())');
  v_rpcs constant text[] := array[
    'public.request_session_change(uuid,text,text,text)', 'public.approve_session_change(uuid,text)',
    'public.reject_session_change(uuid,text)', 'public.withdraw_session_change(uuid)', 'public.session_change_signatures(uuid)'];
  v_ins_r1 constant text := $ir1$  -- B4C:slice7 — a cancelled session takes no sign-in.
  if v_session.status = 'cancelled' then
