  end if;
$ir1$;
  v_ins_r2 constant text := $ir2$  -- B4C:slice7 — a cancelled session has no live code (not an error: the page asks for every session it shows).
  if v_session.status = 'cancelled' then
    return null;
  end if;
$ir2$;
  v_ins_r3 constant text := $ir3$  -- B4C:slice7 — nobody checks in to a cancelled session.
  IF v_session.status = 'cancelled' THEN
