  END IF;
  SELECT count(*) INTO v_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace
     AND proname IN ('request_session_change', 'approve_session_change', 'reject_session_change', 'withdraw_session_change', 'session_change_signatures');
