    END IF;
  END LOOP;
  IF md5(pg_get_functiondef(to_regprocedure(v_guard_sig))) <> v_guard_md5 THEN RAISE EXCEPTION 'PREFLIGHT: the Slice 6 lock guard has drifted. Re-audit.'; END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.open_signin(uuid)'))) <> '38d66e034a5f0d8a71b9e668e358c446' THEN RAISE EXCEPTION 'PREFLIGHT: public.open_signin(uuid) has drifted (live md5 %, pinned 38d66e034a5f0d8a71b9e668e358c446). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.open_signin(uuid)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.current_signin_token(uuid)'))) <> '25970cb998c1f6bf53a56e4da84a57f2' THEN RAISE EXCEPTION 'PREFLIGHT: public.current_signin_token(uuid) has drifted (live md5 %, pinned 25970cb998c1f6bf53a56e4da84a57f2). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.current_signin_token(uuid)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.member_check_in(uuid,text,double precision,double precision,double precision)'))) <> '089a9b4c37c911e632375294985ad150' THEN RAISE EXCEPTION 'PREFLIGHT: public.member_check_in(uuid,text,double precision,double precision,double precision) has drifted (live md5 %, pinned 089a9b4c37c911e632375294985ad150). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.member_check_in(uuid,text,double precision,double precision,double precision)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.set_session_location(uuid,double precision,double precision,integer,text)'))) <> '73122c636c37a2017070804b737b374e' THEN RAISE EXCEPTION 'PREFLIGHT: public.set_session_location(uuid,double precision,double precision,integer,text) has drifted (live md5 %, pinned 73122c636c37a2017070804b737b374e). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.set_session_location(uuid,double precision,double precision,integer,text)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.set_my_session_registration(uuid,text)'))) <> 'f3c7c3e7b41069adddf5cb95e8b10489' THEN RAISE EXCEPTION 'PREFLIGHT: public.set_my_session_registration(uuid,text) has drifted (live md5 %, pinned f3c7c3e7b41069adddf5cb95e8b10489). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.set_my_session_registration(uuid,text)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.finalize_training_session(uuid,integer)'))) <> '6a0f50df0c2e82a3f3f61eda3fe4d129' THEN RAISE EXCEPTION 'PREFLIGHT: public.finalize_training_session(uuid,integer) has drifted (live md5 %, pinned 6a0f50df0c2e82a3f3f61eda3fe4d129). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.finalize_training_session(uuid,integer)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.correct_training_session(uuid,jsonb,uuid[],uuid[],text)'))) <> 'c243fcc63206169f810be3ff2db895ce' THEN RAISE EXCEPTION 'PREFLIGHT: public.correct_training_session(uuid,jsonb,uuid[],uuid[],text) has drifted (live md5 %, pinned c243fcc63206169f810be3ff2db895ce). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.correct_training_session(uuid,jsonb,uuid[],uuid[],text)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.attach_drill_plan_to_session(uuid,uuid)'))) <> '62590b6a9006b28cd009f70e6a11327d' THEN RAISE EXCEPTION 'PREFLIGHT: public.attach_drill_plan_to_session(uuid,uuid) has drifted (live md5 %, pinned 62590b6a9006b28cd009f70e6a11327d). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.attach_drill_plan_to_session(uuid,uuid)'))); END IF;
  IF md5(pg_get_functiondef(to_regprocedure('public.my_department_rollup()'))) <> 'cd368f0fca832bbb0e804c939a7a9d10' THEN RAISE EXCEPTION 'PREFLIGHT: public.my_department_rollup() has drifted (live md5 %, pinned cd368f0fca832bbb0e804c939a7a9d10). Re-audit.', md5(pg_get_functiondef(to_regprocedure('public.my_department_rollup()'))); END IF;
  -- (c) the audit action CHECK, exactly
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.training_session_audit'::regclass AND conname = 'training_session_audit_action_check'
                   AND pg_get_constraintdef(oid) = v_audit_check_old) THEN
