  SELECT count(*) INTO v_n FROM pg_trigger WHERE tgrelid = 'public.training_sessions'::regclass AND NOT tgisinternal;
  IF v_n <> 4 OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.training_sessions'::regclass AND tgname = 'training_session_lock_guard'
