  $ddl$;
  EXECUTE 'CREATE UNIQUE INDEX training_session_requests_one_pending ON public.training_session_requests (session_id) WHERE state = ''pending''';
  EXECUTE 'CREATE INDEX training_session_requests_dept_state_idx ON public.training_session_requests (department_id, state)';
  EXECUTE 'ALTER TABLE public.training_session_requests ENABLE ROW LEVEL SECURITY';
  EXECUTE 'REVOKE ALL ON TABLE public.training_session_requests FROM PUBLIC, anon, authenticated';
  EXECUTE 'REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.training_session_requests FROM service_role';
  -- column grants: everything EXCEPT the two signatures (those come from session_change_signatures, on demand)
  EXECUTE 'GRANT SELECT (id, department_id, session_id, kind, reason, initiator_id, initiator_name, approver_id, approver_name,
                         decision_reason, state, created_at, decided_at) ON TABLE public.training_session_requests TO authenticated';
  EXECUTE $ddl$
    CREATE POLICY "managers read training_session_requests" ON public.training_session_requests
      FOR SELECT TO authenticated
      USING ((department_id = public.my_department_id()) AND (public.is_leadership() OR public.is_training_manager()))
  $ddl$;

  -- =================================================================
  -- 3. THE AUDIT ACTIONS (pinned drop + re-add).
  -- =================================================================
  EXECUTE 'ALTER TABLE public.training_session_audit DROP CONSTRAINT training_session_audit_action_check';
  EXECUTE $ddl$ ALTER TABLE public.training_session_audit ADD CONSTRAINT training_session_audit_action_check
                  CHECK (action IN ('correct', 'reopen', 'finalize', 'cancel', 'restore')) $ddl$;

  -- =================================================================
  -- 4. THE LOCK GUARD — status joins it; INSERT is covered; a cancelled row is locked (D3). date/start_time NOT added.
  -- =================================================================
  EXECUTE $ddl$
    CREATE OR REPLACE FUNCTION public.tg_training_session_lock_guard()
     RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice6 C7 — once a session is FINALIZED or HAS ATTENDANCE (Slice 7: or is CANCELLED), the fields that define the
    -- record (and the attested hours derived from it) change only through the RPCs, which set the transaction-local flag.
    -- Exempt so Finalize / sign-in keep working: done, signin_open, signin_token, location_lat/lng/radius_m,
    -- location_label, and duration_min NULL -> a value on a not-yet-finalized row (Finalize's length prompt).
    -- Slice 7: status ('scheduled'/'cancelled') changes ONLY under the flag (approve_session_change), on any row, and a new
    -- row is always 'scheduled'. date / start_time stay free on an upcoming, unattended session (plain Edit — ruling 3b).
    -- Applies to EVERY writer, the table owner included — a hand fix in the SQL editor must set the flag on purpose.
    begin
      if coalesce(current_setting('b4c.session_correction', true), '') = 'on' then return NEW; end if;
      if TG_OP = 'INSERT' then
        if NEW.status is distinct from 'scheduled' then
          raise exception 'STATUS_LOCKED: a session is created scheduled — cancelling takes the two-person sign-off.' using errcode = '42501';
        end if;
        return NEW;
      end if;
      if NEW.status is distinct from OLD.status then
        raise exception 'STATUS_LOCKED: a session is cancelled or restored only through the two-person sign-off.' using errcode = '42501';
      end if;
      if not (OLD.done is true or OLD.status = 'cancelled' or exists (select 1 from public.session_attendance sa where sa.session_id = OLD.id)) then
        return NEW;
      end if;
      if NEW.title is distinct from OLD.title
         or NEW."date" is distinct from OLD."date"
         or NEW.start_time is distinct from OLD.start_time
         or NEW.audience is distinct from OLD.audience
         or NEW.plan_id is distinct from OLD.plan_id
         or NEW.counts_toward_attendance is distinct from OLD.counts_toward_attendance
         or NEW.is_meeting is distinct from OLD.is_meeting
         or NEW.is_offsite is distinct from OLD.is_offsite
         or NEW.department_id is distinct from OLD.department_id
         or NEW.series_id is distinct from OLD.series_id
         or (NEW.duration_min is distinct from OLD.duration_min
             and not (OLD.duration_min is null and OLD.done is not true)) then
        raise exception 'LOCKED_SESSION: this session is finalized, cancelled or has attendance — change it with Correct (or Restore), which is logged.'
          using errcode = '42501';
      end if;
      return NEW;
    end;
    $fn$
  $ddl$;
  EXECUTE 'DROP TRIGGER training_session_lock_guard ON public.training_sessions';
  EXECUTE $ddl$ CREATE TRIGGER training_session_lock_guard BEFORE INSERT OR UPDATE ON public.training_sessions
                  FOR EACH ROW EXECUTE FUNCTION public.tg_training_session_lock_guard() $ddl$;

  -- =================================================================
  -- 5. THE TWO-PERSON RPCs (R4–R6).
  -- =================================================================
  EXECUTE $ddl$
    CREATE FUNCTION public.request_session_change(p_session_id uuid, p_kind text, p_reason text, p_signature text)
     RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice7 — step 1 of 2: a training manager asks to CANCEL or RESTORE an upcoming, unattended, unfinalized session,
    -- with a reason and their drawn signature. Nothing about the session changes until a DIFFERENT manager approves.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      s        public.training_sessions%rowtype;
      v_id     uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can ask to cancel or restore a session.' using errcode = '42501';
      end if;
      if p_kind is null or p_kind not in ('cancel', 'restore') then raise exception 'BAD_KIND: cancel or restore.'; end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 204800 then
        raise exception 'BAD_SIGNATURE: draw your signature (a PNG, up to 200 KB).';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s."date" < v_today then raise exception 'NOT_UPCOMING: only an upcoming session can be cancelled or restored.'; end if;
      if s.done then raise exception 'FINALIZED: this session is finalized — it happened.'; end if;
      if exists (select 1 from public.session_attendance sa where sa.session_id = s.id) then
        raise exception 'ATTENDED: someone is on this session''s roll — it happened; use Correct instead.';
      end if;
      if p_kind = 'cancel' and s.status = 'cancelled' then raise exception 'ALREADY_CANCELLED: this session is already cancelled.'; end if;
      if p_kind = 'restore' and s.status <> 'cancelled' then raise exception 'NOT_CANCELLED: only a cancelled session can be restored.'; end if;
      if exists (select 1 from public.training_session_requests r where r.session_id = s.id and r.state = 'pending') then
        raise exception 'PENDING: a sign-off is already waiting on this session.';
      end if;
      insert into public.training_session_requests (department_id, session_id, kind, reason, initiator_id, initiator_name, initiator_signature)
      values (v_dept, s.id, p_kind, v_reason, v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'), p_signature)
      returning id into v_id;
      return jsonb_build_object('request_id', v_id, 'state', 'pending', 'kind', p_kind);
    end;
    $fn$
  $ddl$;

  EXECUTE $ddl$
    CREATE FUNCTION public.approve_session_change(p_request_id uuid, p_signature text)
     RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice7 — step 2 of 2: a DIFFERENT training manager, signed in on their own account, approves with their own
    -- drawn signature; the cancel / restore takes effect in this transaction and is logged in training_session_audit.
    -- A request that is no longer valid (drill date passed; session attended / finalized / already in the target state)
    -- is EXPIRED and returned as such (D1) — not raised, so the expiry persists.
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      v_today date := (now() at time zone 'America/Chicago')::date;
      r       public.training_session_requests%rowtype;
      s       public.training_sessions%rowtype;
      v_new   text; v_n integer; v_audit uuid; v_name text;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can sign off a cancel or restore.' using errcode = '42501';
      end if;
      if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 204800 then
        raise exception 'BAD_SIGNATURE: draw your signature (a PNG, up to 200 KB).';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id = v_me then
        raise exception 'SAME_PERSON: a second training manager has to sign off — not the one who asked.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = r.session_id for update;
      v_new := case r.kind when 'cancel' then 'cancelled' else 'scheduled' end;
      if s."date" < v_today or s.done or s.status = v_new
         or exists (select 1 from public.session_attendance sa where sa.session_id = s.id) then
        update public.training_session_requests set state = 'expired', decided_at = now() where id = r.id;
        return jsonb_build_object('request_id', r.id, 'state', 'expired');
      end if;
      select count(*) into v_n from public.session_attendance where session_id = s.id;   -- 0 by the check above
      v_name := coalesce((select m.name from public.members m where m.id = v_me), 'Unknown');
      perform set_config('b4c.session_correction', 'on', true);
      update public.training_sessions
         set status = v_new,
             signin_open = case when v_new = 'cancelled' then false else signin_open end,      -- D5
             signin_token = case when v_new = 'cancelled' then null else signin_token end
       where id = s.id;
      perform set_config('b4c.session_correction', '', true);
      update public.training_session_requests
         set state = 'approved', approver_id = v_me, approver_name = v_name, approver_signature = p_signature, decided_at = now()
       where id = r.id;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes, roster_before, roster_after)
      values (v_dept, s.id, r.kind, v_me, v_name, r.reason,
              jsonb_build_object('status', jsonb_build_object('old', s.status, 'new', v_new), 'request_id', r.id,
                                 'initiator', jsonb_build_object('id', r.initiator_id, 'name', r.initiator_name)),
              v_n, v_n)
      returning id into v_audit;
      return jsonb_build_object('request_id', r.id, 'state', 'approved', 'status', v_new, 'audit_id', v_audit);
    end;
    $fn$
  $ddl$;

  EXECUTE $ddl$
    CREATE FUNCTION public.reject_session_change(p_request_id uuid, p_reason text)
     RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice7 — another training manager declines a pending request, with a reason (D8). Nothing about the session changes.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_reason text := btrim(coalesce(p_reason, ''));
      r        public.training_session_requests%rowtype;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can decline a cancel or restore.' using errcode = '42501';
      end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id = v_me then raise exception 'USE_WITHDRAW: you asked — withdraw it instead.'; end if;
      update public.training_session_requests
         set state = 'rejected', approver_id = v_me, approver_name = coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
             decision_reason = v_reason, decided_at = now()
       where id = r.id;
      return jsonb_build_object('request_id', r.id, 'state', 'rejected');
    end;
    $fn$
  $ddl$;

  EXECUTE $ddl$
    CREATE FUNCTION public.withdraw_session_change(p_request_id uuid)
     RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice7 — the initiator takes back their own pending request (D8). Nothing about the session changes.
    declare
      v_dept uuid := public.my_department_id();
      v_me   uuid := public.my_member_id();
      r      public.training_session_requests%rowtype;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can withdraw a request.' using errcode = '42501';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id <> v_me then raise exception 'NOT_YOURS: only the person who asked can withdraw it.' using errcode = '42501'; end if;
      update public.training_session_requests set state = 'withdrawn', decided_at = now() where id = r.id;
      return jsonb_build_object('request_id', r.id, 'state', 'withdrawn');
    end;
    $fn$
  $ddl$;

  EXECUTE $ddl$
    CREATE FUNCTION public.session_change_signatures(p_request_id uuid)
     RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
    AS $fn$
    -- B4C:slice7 D4 — the two drawn signatures, on demand ("View signatures"). Same read gate as the table.
    declare
      v_dept uuid := public.my_department_id();
      r      public.training_session_requests%rowtype;
    begin
      if v_dept is null or not (coalesce(public.is_leadership(), false) or coalesce(public.is_training_manager(), false)) then
        raise exception 'Only department leadership or a training manager can view these signatures.' using errcode = '42501';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      return jsonb_build_object('request_id', r.id, 'initiator_name', r.initiator_name, 'initiator_signature', r.initiator_signature,
                                'approver_name', r.approver_name, 'approver_signature', r.approver_signature);
    end;
    $fn$
  $ddl$;

  -- =================================================================
  -- 6. THE 9 REPOINTED READERS — each the verbatim live body + one inserted block (CREATE OR REPLACE keeps owner + ACL).
  -- =================================================================
  -- open_signin: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r1$CREATE OR REPLACE FUNCTION public.open_signin(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.training_sessions%rowtype;
  v_token   text;
  v_start   timestamptz;
  v_end     timestamptz;
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to open a sign-in for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from public.my_department_id() then
    raise exception 'That training session was not found in your department.';
  end if;
  if v_session.done then
    raise exception 'This session is complete — you cannot open a sign-in.';
  end if;
  -- B4C:slice7 — a cancelled session takes no sign-in.
  if v_session.status = 'cancelled' then
    raise exception 'CANCELLED: this session was cancelled — it can''t take a sign-in.';
  end if;

  /* THE SIGN-IN WINDOW — see the file header for why both bounds exist and why
     they are asymmetric in intent.

     start_time is nullable: an all-day session with no time reads as midnight,
     so its window opens at midnight the day before. duration_min is nullable
     too: a null duration treats the session as instantaneous, so the window
     still closes 24 hours after its start rather than never.

     Central is hardcoded — see the header. */
  v_start := (v_session.date + coalesce(v_session.start_time, time '00:00'))
               at time zone 'America/Chicago';
  v_end   := v_start + make_interval(mins => coalesce(v_session.duration_min, 0));

  if now() < v_start - interval '24 hours' then
    raise exception 'This training is scheduled for %. Its sign-in can be opened from 24 hours before it starts.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  if now() > v_end + interval '24 hours' then
    raise exception 'This training was scheduled for % and its sign-in window has closed. To record who attended, mark them present on the session''s roster instead.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  -- ---- NEW IN C3 ----
  if v_session.is_offsite
     and (v_session.location_lat is null or v_session.location_lng is null) then
    raise exception 'Set this drill''s location first — you have to be on site, then tap "Use my location".';
  end if;
  -- ---- END NEW ----

  v_token := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
  update public.training_sessions
    set signin_token = v_token, signin_open = true
  where id = p_session_id;
  return v_token;
end;
$function$
$r1$;

  -- current_signin_token: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r2$CREATE OR REPLACE FUNCTION public.current_signin_token(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.training_sessions%rowtype;
begin
  -- ---- gate copied verbatim from open_signin ----
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to open a sign-in for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from public.my_department_id() then
    raise exception 'That training session was not found in your department.';
  end if;
  -- ---- end copied gate ----
  -- B4C:slice7 — a cancelled session has no live code (not an error: the page asks for every session it shows).
  if v_session.status = 'cancelled' then
    return null;
  end if;

  -- No live sign-in, no code. Not an error: the officer's page asks for every
  -- session it is showing, and most of them are legitimately closed.
  if not coalesce(v_session.signin_open, false) then
    return null;
  end if;

  return v_session.signin_token;
end;
$function$
$r2$;

  -- member_check_in: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r3$CREATE OR REPLACE FUNCTION public.member_check_in(p_session_id uuid, p_token text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_accuracy double precision DEFAULT NULL::double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session  public.training_sessions%ROWTYPE;
  v_member   uuid := public.my_member_id();
  v_dept     uuid := public.my_department_id();
  v_recorded boolean := false;
  v_verified boolean := false;
  v_pinned   boolean := true;   -- fail closed if the department row does not resolve
BEGIN
  IF v_member IS NULL OR v_dept IS NULL THEN
    RAISE EXCEPTION 'We could not match your login to a member record.';
  END IF;

  SELECT * INTO v_session FROM public.training_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That training session was not found.';
  END IF;

  IF v_session.department_id IS DISTINCT FROM v_dept THEN
    RAISE EXCEPTION 'That session is not in your department.';
  END IF;

  IF v_session.done THEN
    RAISE EXCEPTION 'This session is complete — attendance is locked.';
  END IF;
  -- B4C:slice7 — nobody checks in to a cancelled session.
  IF v_session.status = 'cancelled' THEN
    RAISE EXCEPTION 'CANCELLED: this session was cancelled — there is nothing to check in to.';
  END IF;

  -- ---- ADDED: the sign-in must be OPEN, not merely hold a matching code ----
  -- Without this, "is this sign-in open?" is answered indirectly, by whether
  -- some other function remembered to clear the token when closing. That is an
  -- invariant maintained by one writer and breakable by any direct UPDATE.
  IF NOT coalesce(v_session.signin_open, false) THEN
    RAISE EXCEPTION 'Sign-in for this session has closed — ask your training officer to reopen it.';
  END IF;
  -- ---- END ADDED ----

  IF v_session.signin_token IS NULL OR v_session.signin_token <> p_token THEN
    RAISE EXCEPTION 'Invalid or expired sign-in code — scan the current QR.';
  END IF;

  INSERT INTO public.session_attendance (department_id, session_id, member_id, checked_in_at)
  VALUES (v_dept, p_session_id, v_member, now())
  ON CONFLICT (session_id, member_id) DO NOTHING;
  v_recorded := FOUND;

  -- ---- CHANGED IN C3: branch on the FLAG, not on whether coordinates exist ----
  IF v_session.is_offsite THEN
    IF v_session.location_lat IS NOT NULL AND v_session.location_lng IS NOT NULL THEN
      v_verified := public.is_at_point(
        v_session.location_lat, v_session.location_lng,
        coalesce(v_session.location_radius_m,
                 (SELECT station_radius_m FROM public.departments WHERE id = v_dept),
                 400),
        p_lat, p_lng, p_accuracy);
    ELSE
      -- Off-site, but nobody has captured where. NEVER fall back to the station:
      -- they are not there. No clock; attendance above still stands.
      v_verified := false;
    END IF;
    v_pinned := true;   -- an off-site session is always "pinned" for gate purposes
  ELSE
    v_verified := public.is_at_station(v_dept, p_lat, p_lng, p_accuracy);
    SELECT (station_lat IS NOT NULL AND station_lng IS NOT NULL)
      INTO v_pinned
      FROM public.departments
     WHERE id = v_dept;
  END IF;
  -- ---- END CHANGED BLOCK ----

  IF v_verified OR NOT v_pinned THEN
    INSERT INTO public.station_presence (department_id, member_id, verified, source, kind, session_id)
    VALUES (v_dept, v_member, v_verified, 'geo', 'training', p_session_id)
    ON CONFLICT (member_id, session_id) WHERE kind = 'training' AND session_id IS NOT NULL DO NOTHING;
  END IF;

  IF v_recorded THEN RETURN 'recorded'; ELSE RETURN 'already'; END IF;
END;
$function$
$r3$;

  -- set_session_location: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r4$CREATE OR REPLACE FUNCTION public.set_session_location(p_session_id uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_m integer DEFAULT NULL::integer, p_label text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept    uuid := public.my_department_id();
  v_session public.training_sessions%rowtype;
  v_radius  integer;
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to set the location for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from v_dept then
    raise exception 'That training session was not found in your department.';
  end if;
  if v_session.done then
    raise exception 'This session is complete — its location can no longer be changed.';
  end if;
  -- B4C:slice7 — a cancelled session's location is frozen with it.
  if v_session.status = 'cancelled' then
    raise exception 'CANCELLED: this session was cancelled — restore it before changing its location.';
  end if;

  -- clear: back to verifying against the station. Allowed whatever the flag says.
  if p_lat is null and p_lng is null then
    update public.training_sessions
       set location_lat = null, location_lng = null,
           location_radius_m = null, location_label = null
     where id = p_session_id;
    return;
  end if;

  if p_lat is null or p_lng is null then
    raise exception 'We could not read your location — try again, or leave the drill at the station.';
  end if;

  -- ---- NEW IN C3: only an off-site drill may carry a location ----
  if not v_session.is_offsite then
    raise exception 'Mark this drill as off-site before setting its location.';
  end if;
  -- ---- END NEW ----

  -- store the radius explicitly so the record is self-describing later
  v_radius := coalesce(p_radius_m,
                       (select station_radius_m from public.departments where id = v_dept),
                       400);

  update public.training_sessions
     set location_lat      = p_lat,
         location_lng      = p_lng,
         location_radius_m = v_radius,
         location_label    = nullif(btrim(coalesce(p_label, '')), '')
   where id = p_session_id;
end;
$function$
$r4$;

  -- set_my_session_registration: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r5$CREATE OR REPLACE FUNCTION public.set_my_session_registration(p_session_id uuid, p_status text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:session_registrations — self-only, department-scoped, audience-eligible. Never touches attendance.
declare
  v_me uuid := public.my_member_id();
  v_my_dept uuid := public.my_department_id();
  v_access text[];
  v_sess record;
begin
  if p_status is null or p_status not in ('coming', 'maybe', 'not_coming') then
    raise exception 'Choose Coming, Maybe, or Not coming';
  end if;
  if v_me is null or v_my_dept is null then
    raise exception 'We could not match your login to a member record.';
  end if;
  select department_id, audience, done into v_sess from public.training_sessions where id = p_session_id;
  if not found or v_sess.department_id is distinct from v_my_dept then
    raise exception 'Not in your department';
  end if;
  if coalesce(v_sess.done, false) then
    raise exception 'This session is closed';
  end if;
  -- B4C:slice7 — no RSVPs to a cancelled session (existing ones are kept, unchanged).
  if exists (select 1 from public.training_sessions where id = p_session_id and status = 'cancelled') then
    raise exception 'CANCELLED: this session was cancelled';
  end if;
  select access into v_access from public.members where id = v_me and department_id = v_my_dept;
  if not found then
    raise exception 'Not in your department';
  end if;
  -- audience eligibility — the client's rollFor, server-side
  if v_sess.audience = 'board' and not (coalesce(v_access, '{}') && array['Board Member']::text[]) then
    raise exception 'Not eligible for this session';
  end if;
  if v_sess.audience = 'leadership' and not (coalesce(v_access, '{}') && array['Project Admin', 'Department Admin', 'Board Member', 'Officer']::text[]) then
    raise exception 'Not eligible for this session';
  end if;
  insert into public.session_registrations (session_id, member_id, department_id, status)
  values (p_session_id, v_me, v_my_dept, p_status)
  on conflict (session_id, member_id) do update set status = excluded.status, updated_at = now();
  return p_status;
end;
$function$
$r5$;

  -- finalize_training_session: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r6$CREATE OR REPLACE FUNCTION public.finalize_training_session(p_session_id uuid, p_duration_min integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 C4 — what the client's finalize does today (done, plus a FIRST length), logged. R4: a category's
    -- last_iso becomes greatest(existing, the drill's date) — and only when the roll is non-empty. If the session was
    -- reopened, the roster change since that Reopen is logged here (D4).
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      s       public.training_sessions%rowtype;
      v_dur   integer;
      v_now   uuid[]; v_snap uuid[]; v_last text;
      v_add   uuid[] := '{}'; v_rem uuid[] := '{}';
      v_diff  jsonb := jsonb_build_object('done', jsonb_build_object('old', false, 'new', true));
      v_audit uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can finalize a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s.done then raise exception 'ALREADY_FINALIZED: this session is already finalized.'; end if;
      -- B4C:slice7 — a cancelled drill didn't happen: nothing to finalize.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before finalizing.'; end if;
      if s.signin_open then raise exception 'SIGNIN_OPEN: close the QR sign-in first.'; end if;
      if p_duration_min is not null then
        if p_duration_min < 1 or p_duration_min > 1440 then raise exception 'BAD_VALUE: a length is 1–1440 minutes.'; end if;
        if s.duration_min is not null and s.duration_min <> p_duration_min then
          raise exception 'USE_CORRECT: this drill already has a length — change it with Correct.';
        end if;
      end if;
      v_dur := coalesce(s.duration_min, p_duration_min);
      if v_dur is distinct from s.duration_min then
        v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', v_dur));
      end if;
      select coalesce(array_agg(sa.member_id order by sa.member_id), '{}') into v_now
        from public.session_attendance sa where sa.session_id = s.id;
      -- the latest log entry for this session: if it is a Reopen, compare the roll now with the roll then
      select a.action, a.roster_snapshot into v_last, v_snap
        from public.training_session_audit a where a.session_id = s.id order by a.seq desc limit 1;
      if v_last = 'reopen' then
        select coalesce(array_agg(x order by x), '{}') into v_add from unnest(v_now) x where x <> all (coalesce(v_snap, '{}'));
        select coalesce(array_agg(x order by x), '{}') into v_rem from unnest(coalesce(v_snap, '{}')) x where x <> all (v_now);
      end if;
      update public.training_sessions set done = true, duration_min = v_dur where id = s.id;
      if s.plan_id is not null and cardinality(v_now) > 0 then
        update public.training_plans set last_iso = greatest(coalesce(last_iso, s."date"), s."date") where id = s.plan_id;
      end if;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'finalize', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              null, v_diff, v_add, v_rem,
              cardinality(v_now) - cardinality(v_add) + cardinality(v_rem), cardinality(v_now))
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'present', cardinality(v_now), 'duration_min', v_dur,
                                'roster_added', to_jsonb(v_add), 'roster_removed', to_jsonb(v_rem));
    end;
    $function$
$r6$;

  -- correct_training_session: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r7$CREATE OR REPLACE FUNCTION public.correct_training_session(p_session_id uuid, p_changes jsonb, p_add uuid[], p_remove uuid[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 — the gated, logged correction of a LOCKED session (finalized, sign-in open, or anyone on the roll).
    -- C1 hybrid: a training manager within 14 days of the drill (Central); older = Department Admin only (D1: the ROLE,
    -- never Project Admin). C2: a reason of 10+ characters. Fields: §2a whitelist only. Roster: add/remove in the same
    -- transaction; the membership-window triggers still run, and a refusal there aborts the whole call (nothing written).
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      v_chg    jsonb := coalesce(p_changes, '{}'::jsonb);
      v_keys   constant text[] := array['title', 'date', 'start_time', 'duration_min', 'audience', 'plan_id',
                                        'counts_toward_attendance', 'is_meeting', 'is_offsite', 'location_label'];
      s        public.training_sessions%rowtype;
      v_bad    text[];
      n_title text; n_date date; n_start time; n_dur integer; n_aud text; n_plan uuid;
      n_counts boolean; n_meet boolean; n_off boolean; n_label text;
      v_diff   jsonb := '{}'::jsonb;
      v_add    uuid[]; v_rem uuid[];
      v_before integer; v_after integer;
      v_audit  uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can correct a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      -- B4C:slice7 — a cancelled session is restored (two-person), not corrected.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before correcting it.'; end if;
      if not (s.done or s.signin_open or exists (select 1 from public.session_attendance sa where sa.session_id = s.id)) then
        raise exception 'NOT_LOCKED: this session can still be edited normally — no correction needed.';
      end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if jsonb_typeof(v_chg) <> 'object' then raise exception 'BAD_CHANGES: changes must be a JSON object.'; end if;
      select array_agg(k order by k) into v_bad from jsonb_object_keys(v_chg) k where k <> all (v_keys);
      if v_bad is not null then raise exception 'UNKNOWN_FIELD: % cannot be corrected here.', array_to_string(v_bad, ', '); end if;

      -- the corrected values (an absent key = unchanged)
      n_title  := case when v_chg ? 'title'        then btrim(v_chg->>'title') else s.title end;
      n_date   := case when v_chg ? 'date'         then (v_chg->>'date')::date else s."date" end;
      n_start  := case when v_chg ? 'start_time'   then nullif(v_chg->>'start_time', '')::time else s.start_time end;
      n_dur    := case when v_chg ? 'duration_min' then nullif(v_chg->>'duration_min', '')::integer else s.duration_min end;
      n_aud    := case when v_chg ? 'audience'     then v_chg->>'audience' else s.audience end;
      n_plan   := case when v_chg ? 'plan_id'      then nullif(v_chg->>'plan_id', '')::uuid else s.plan_id end;
      n_counts := case when v_chg ? 'counts_toward_attendance' then (v_chg->>'counts_toward_attendance')::boolean else s.counts_toward_attendance end;
      n_meet   := case when v_chg ? 'is_meeting'   then (v_chg->>'is_meeting')::boolean else s.is_meeting end;
      n_off    := case when v_chg ? 'is_offsite'   then (v_chg->>'is_offsite')::boolean else s.is_offsite end;
      n_label  := case when v_chg ? 'location_label' then nullif(btrim(v_chg->>'location_label'), '') else s.location_label end;
      if n_title is null or n_title = '' then raise exception 'BAD_VALUE: a session needs a title.'; end if;
      if n_date is null then raise exception 'BAD_VALUE: a session needs a date.'; end if;
      if n_counts is null or n_off is null then raise exception 'BAD_VALUE: counts_toward_attendance / is_offsite cannot be blank.'; end if;
      if n_dur is not null and (n_dur < 1 or n_dur > 1440) then raise exception 'BAD_VALUE: a length is 1–1440 minutes.'; end if;
      if n_aud is null or n_aud not in ('everyone', 'leadership', 'board') then raise exception 'BAD_VALUE: unknown audience.'; end if;
      if n_plan is distinct from s.plan_id and n_plan is not null
         and not exists (select 1 from public.training_plans tp where tp.id = n_plan and tp.department_id = v_dept) then
        raise exception 'BAD_VALUE: that training category is not in your department.';
      end if;
      if n_aud <> 'everyone' then n_meet := false; end if;      -- only an everyone session carries the meeting flag (client rule)
      if not n_off then n_label := null; end if;                -- off -> no label / coordinates (coords CHECK)

      -- C1 hybrid (D2: the earlier of the current and corrected date)
      if least(s."date", n_date) < v_today - 14
         and not exists (select 1 from public.members m where m.id = v_me and m.department_id = v_dept
                           and m.status in ('Active', 'Probationary') and m.access && array['Department Admin']::text[]) then
        raise exception 'DA_ONLY: correcting a drill more than 14 days old is for a Department Admin.' using errcode = '42501';
      end if;

      -- old -> new, only what actually changes
      if n_title  is distinct from s.title        then v_diff := v_diff || jsonb_build_object('title',        jsonb_build_object('old', s.title, 'new', n_title)); end if;
      if n_date   is distinct from s."date"       then v_diff := v_diff || jsonb_build_object('date',         jsonb_build_object('old', s."date", 'new', n_date)); end if;
      if n_start  is distinct from s.start_time   then v_diff := v_diff || jsonb_build_object('start_time',   jsonb_build_object('old', s.start_time, 'new', n_start)); end if;
      if n_dur    is distinct from s.duration_min then v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', n_dur)); end if;
      if n_aud    is distinct from s.audience     then v_diff := v_diff || jsonb_build_object('audience',     jsonb_build_object('old', s.audience, 'new', n_aud)); end if;
      if n_plan   is distinct from s.plan_id      then v_diff := v_diff || jsonb_build_object('plan_id',      jsonb_build_object('old', s.plan_id, 'new', n_plan)); end if;
      if n_counts is distinct from s.counts_toward_attendance then v_diff := v_diff || jsonb_build_object('counts_toward_attendance', jsonb_build_object('old', s.counts_toward_attendance, 'new', n_counts)); end if;
      if n_meet   is distinct from s.is_meeting   then v_diff := v_diff || jsonb_build_object('is_meeting',   jsonb_build_object('old', s.is_meeting, 'new', n_meet)); end if;
      if n_off    is distinct from s.is_offsite   then v_diff := v_diff || jsonb_build_object('is_offsite',   jsonb_build_object('old', s.is_offsite, 'new', n_off)); end if;
      if n_label  is distinct from s.location_label then v_diff := v_diff || jsonb_build_object('location_label', jsonb_build_object('old', s.location_label, 'new', n_label)); end if;
      if not n_off and (s.location_lat is not null or s.location_lng is not null) then
        v_diff := v_diff || jsonb_build_object('location', jsonb_build_object('old', jsonb_build_object('lat', s.location_lat, 'lng', s.location_lng, 'radius_m', s.location_radius_m), 'new', null));
      end if;

      -- roster deltas: deduped, disjoint, truthful (no "adding" someone already there, no "removing" someone absent)
      select coalesce(array_agg(distinct x order by x), '{}') into v_add from unnest(coalesce(p_add, '{}')) x where x is not null;
      select coalesce(array_agg(distinct x order by x), '{}') into v_rem from unnest(coalesce(p_remove, '{}')) x where x is not null;
      if v_add && v_rem then raise exception 'BAD_ROSTER: a member cannot be both added and removed.'; end if;
      if exists (select 1 from unnest(v_add) x where not exists (select 1 from public.members m where m.id = x and m.department_id = v_dept)) then
        raise exception 'BAD_ROSTER: someone being added is not a member of your department.';
      end if;
      if exists (select 1 from unnest(v_add) x where exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being added is already on the roll.';
      end if;
      if exists (select 1 from unnest(v_rem) x where not exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being removed is not on the roll.';
      end if;
      if v_diff = '{}'::jsonb and cardinality(v_add) = 0 and cardinality(v_rem) = 0 then
        raise exception 'NO_CHANGE: nothing to correct.';
      end if;

      select count(*) into v_before from public.session_attendance where session_id = s.id;
      perform set_config('b4c.session_correction', 'on', true);
      -- removals BEFORE the date moves (someone leaving the roll must not block a date their window excludes);
      -- additions AFTER (their window is checked against the corrected date)
      delete from public.session_attendance where session_id = s.id and member_id = any (v_rem);
      if v_diff <> '{}'::jsonb then
        update public.training_sessions
           set title = n_title, "date" = n_date, start_time = n_start, duration_min = n_dur, audience = n_aud, plan_id = n_plan,
               counts_toward_attendance = n_counts, is_meeting = n_meet, is_offsite = n_off, location_label = n_label,
               location_lat = case when n_off then location_lat end,
               location_lng = case when n_off then location_lng end,
               location_radius_m = case when n_off then location_radius_m end
         where id = s.id;
      end if;
      insert into public.session_attendance (department_id, session_id, member_id, checked_in_at)
      select v_dept, s.id, x, now() from unnest(v_add) x;
      perform set_config('b4c.session_correction', '', true);
      select count(*) into v_after from public.session_attendance where session_id = s.id;

      perform public.recompute_training_plan_last_iso(s.plan_id);
      if n_plan is distinct from s.plan_id then perform public.recompute_training_plan_last_iso(n_plan); end if;

      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'correct', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              v_reason, v_diff, v_add, v_rem, v_before, v_after)
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'changes', v_diff, 'roster_added', to_jsonb(v_add),
                                'roster_removed', to_jsonb(v_rem), 'roster_before', v_before, 'roster_after', v_after);
    end;
    $function$
$r7$;

  -- attach_drill_plan_to_session: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r8$CREATE OR REPLACE FUNCTION public.attach_drill_plan_to_session(p_plan_id uuid, p_session_id uuid)
 RETURNS session_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — attach a library plan to a training session in the caller's OWN department, as an ordinary
  -- session_plans row (the existing View plan renders its ai_text). One attachment per (session, plan).
  declare v_dept uuid := public.my_department_id(); v_p public.drill_plans; v_row public.session_plans;
          v_c jsonb; v_who text; L text[] := array[]::text[]; s jsonb; i int := 0;
  begin
    if v_dept is null or not coalesce(public.is_training_manager(), false) then
      raise exception 'Only a Department Admin or training officer can attach drill plans.';
    end if;
    select * into v_p from public.drill_plans where id = p_plan_id and department_id = v_dept for update;
    if not found then raise exception 'That drill plan is not in your department.'; end if;
    if not exists (select 1 from public.training_sessions where id = p_session_id and department_id = v_dept) then
      raise exception 'That session is not in your department.';
    end if;
    -- B4C:slice7 — no plans onto a cancelled session (R7).
    if exists (select 1 from public.training_sessions where id = p_session_id and status = 'cancelled') then
      raise exception 'CANCELLED: that session was cancelled — restore it before attaching a plan.';
    end if;
    if exists (select 1 from public.session_plans where session_id = p_session_id and drill_plan_id = p_plan_id) then
      raise exception 'That plan is already attached to this session.';
    end if;
    v_c := v_p.content;
    -- the Quick Run Sheet, then the full plan — the layout serializeDrillPlan writes and the plan viewer splits on
    L := L || '## Quick Run Sheet'::text;
    if v_p.duration_min is not null then L := L || ''::text || ('Total time: ' || v_p.duration_min || ' min'); end if;
    if jsonb_typeof(v_c -> 'run_of_show') = 'array' then
      for s in select x from jsonb_array_elements(v_c -> 'run_of_show') x loop
        i := i + 1;
        if jsonb_typeof(s) = 'object' then
          L := L || ''::text || ('**' || i || '. ' || coalesce(nullif(s ->> 't', ''), 'Step') || '**');
          if coalesce(s ->> 'd', '') <> '' then L := L || ('- ' || (s ->> 'd')); end if;
        else
          L := L || ''::text || ('**' || i || '. ' || (s #>> '{}') || '**');
        end if;
      end loop;
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '**Safety first:**'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    L := L || ''::text || ('## ' || v_p.title || ' — Drill Plan');
    if coalesce(v_c ->> 'summary', '') <> '' then L := L || ''::text || (v_c ->> 'summary'); end if;
    if v_p.duration_min is not null then L := L || ''::text || ('Duration: ' || v_p.duration_min || ' minutes'); end if;
    if jsonb_typeof(v_c -> 'objectives') = 'array' and jsonb_array_length(v_c -> 'objectives') > 0 then
      L := L || ''::text || '## Objectives'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'objectives') x);
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '## Safety notes'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    if jsonb_typeof(v_c -> 'materials') = 'array' and jsonb_array_length(v_c -> 'materials') > 0 then
      L := L || ''::text || '## Equipment'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'materials') x);
    end if;
    select name into v_who from public.members where id = public.my_member_id();
    insert into public.session_plans (department_id, session_id, title, source, ai_text, created_by, drill_plan_id)
    values (v_dept, p_session_id, v_p.title, 'ai', array_to_string(L, E'\n'), coalesce(v_who, 'Unknown'), p_plan_id)
    returning * into v_row;
    return v_row;
  end;
  $function$
$r8$;

  -- my_department_rollup: the live body + the B4C:slice7 block (see docs/review/training_slice7_db_READER_DIFFS.patch)
  EXECUTE $r9$CREATE OR REPLACE FUNCTION public.my_department_rollup()
 RETURNS TABLE(department_id uuid, department_name text, station text, city text, can_manage boolean, admin_name text, admin_email text, health text, last_activity timestamp with time zone, days_since_activity integer, active_members_30d bigint, member_count bigint, documents_count bigint, apparatus_count bigint, training_sessions_count bigint, profile_complete boolean, members_no_email_count bigint, documents_no_text_count bigint, expiring_certs_count bigint, expired_certs_count bigint, overdue_duties_count bigint, open_action_items_count bigint, my_attendance_pct integer, my_attendance_total integer, my_attendance_attended integer, my_certs_current integer, my_certs_expiring integer, my_certs_expired integer, my_open_duties integer, my_overdue_duties integer, my_next_event_date date, my_next_event_title text, my_next_event_type text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  with base as (
    select
      d.id as department_id, d.name as department_name, d.station, d.city,

      -- WHAT THE CALLER IS **HERE**. me.my_access is this person's roles at THIS
      -- department; a leader at one station is not a leader at the next.
      coalesce(me.my_access && array['Board Member','Department Admin','Officer']::text[], false) as can_manage,
      -- is_leader()'s array, used ONLY to decide whether restricted drills count
      -- toward this member's own attendance rate (mirrors MemberDashboard).
      coalesce(me.my_access && array['Project Admin','Department Admin','Board Member','Officer']::text[], false) as my_is_leader,
      me.my_mid,

      (select m.name from members m
         where m.department_id = d.id and m.access && array['Department Admin']::text[]
           and m.email is not null and btrim(m.email) <> ''
         order by m.created_at asc nulls last limit 1) as admin_name,
      (select lower(m.email) from members m
         where m.department_id = d.id and m.access && array['Department Admin']::text[]
           and m.email is not null and btrim(m.email) <> ''
         order by m.created_at asc nulls last limit 1) as admin_email,
      greatest(
        (select max(sa.checked_in_at) from session_attendance sa where sa.department_id = d.id),
        (select max(dl.done_at)       from duty_log dl          where dl.department_id = d.id),
        (select max(ai.created_at)    from action_items ai      where ai.department_id = d.id),
        (select max(doc.created_at)   from documents doc        where doc.department_id = d.id
                                                                  and doc.deleted_at is null and doc.archived_at is null),
        (select max(an.created_at)    from announcements an     where an.department_id = d.id),
        (select max(ts.created_at)    from training_sessions ts where ts.department_id = d.id)
      ) as last_activity,
      (select count(distinct mid) from (
          select sa.member_id as mid from session_attendance sa
            where sa.department_id = d.id and sa.checked_in_at >= now() - interval '30 days'
          union
          select dl.done_by from duty_log dl
            where dl.department_id = d.id and dl.done_at >= now() - interval '30 days'
          union
          select ai.completed_by from action_items ai
            where ai.department_id = d.id and ai.completed_at >= now() - interval '30 days'
       ) act where mid is not null) as active_members_30d,
      (select count(*) from members mm where mm.department_id = d.id) as member_count,
      (select count(*) from documents dc where dc.department_id = d.id
                                          and dc.deleted_at is null and dc.archived_at is null) as documents_count,
      (select count(*) from apparatus ap where ap.department_id = d.id) as apparatus_count,
      (select count(*) from training_sessions ts where ts.department_id = d.id) as training_sessions_count,
      (    d.tagline is not null and btrim(d.tagline) <> ''
       and d.voice is not null and btrim(d.voice) <> ''
       and d.primary_color is not null and d.primary_color <> '#B11E2A'
       and d.accent_color is not null and d.accent_color <> '#1F4E79') as profile_complete,
      (select count(*) from members mm where mm.department_id = d.id
                                        and (mm.email is null or btrim(mm.email) = '')) as members_no_email_count,
      (select count(*) from documents dc where dc.department_id = d.id
                                          and dc.deleted_at is null and dc.archived_at is null
                                          and (dc.content_text is null or btrim(dc.content_text) = '')) as documents_no_text_count,
      (select count(*) from certs c where c.department_id = d.id and public.valid_exp_ym(c.exp)
           and not public.cert_never_expires(c.no_expiry, c.cert_type_id, c.department_id)
           and (split_part(c.exp,'-',1)::int*12 + split_part(c.exp,'-',2)::int)
             - (extract(year from now())::int*12 + extract(month from now())::int) between 0 and 3) as expiring_certs_count,
      (select count(*) from certs c where c.department_id = d.id and public.valid_exp_ym(c.exp)
           and not public.cert_never_expires(c.no_expiry, c.cert_type_id, c.department_id)
           and (split_part(c.exp,'-',1)::int*12 + split_part(c.exp,'-',2)::int)
             - (extract(year from now())::int*12 + extract(month from now())::int) < 0) as expired_certs_count,
      (select count(*) from duties du where du.department_id = d.id
                                       and du.done = false and du.due_date is not null and du.due_date < current_date) as overdue_duties_count,
      (select count(*) from action_items ai where ai.department_id = d.id and ai.status = 'open') as open_action_items_count,

      -- ================= MEMBER-SCOPED =================
      -- Every one of these is filtered to me.my_mid. They are computed for all
      -- callers (they are the caller's OWN data, never anybody else's) and are
      -- what a non-managing member sees in place of the leadership figures.

      -- ATTENDANCE, this calendar month, mirroring MemberDashboard.monthRate:
      -- a drill counts only if it is done, has at least one recorded attendee,
      -- is not flagged optional, and — for a non-leader — is not restricted.
      -- The "has an attendee" test is what makes this "recorded drills" rather
      -- than "scheduled drills"; a session nobody signed into is not a missed
      -- drill, it is an unheld one.
      (select count(*) from training_sessions ts
        where ts.department_id = d.id and ts.done
          and date_trunc('month', ts.date) = date_trunc('month', current_date)
          and coalesce(ts.counts_toward_attendance, true) <> false
          and (coalesce(me.my_access && array['Project Admin','Department Admin','Board Member','Officer']::text[], false)
               or coalesce(ts.audience,'everyone') not in ('leadership','board'))
          and exists (select 1 from session_attendance sa where sa.session_id = ts.id)
      )::int as my_attendance_total,
      (select count(*) from training_sessions ts
        where ts.department_id = d.id and ts.done
          and date_trunc('month', ts.date) = date_trunc('month', current_date)
          and coalesce(ts.counts_toward_attendance, true) <> false
          and (coalesce(me.my_access && array['Project Admin','Department Admin','Board Member','Officer']::text[], false)
               or coalesce(ts.audience,'everyone') not in ('leadership','board'))
          and exists (select 1 from session_attendance sa
                       where sa.session_id = ts.id and sa.member_id = me.my_mid)
      )::int as my_attendance_attended,

      -- CERTS — same month-arithmetic and same regex as the leadership columns
      -- above, filtered to this member. The three buckets are disjoint, so a
      -- cert is current, expiring, or expired, never two of them.
      (select count(*) from certs c where c.department_id = d.id and c.member_id = me.my_mid
           and (public.cert_never_expires(c.no_expiry, c.cert_type_id, c.department_id)
                or (public.valid_exp_ym(c.exp)
           and (split_part(c.exp,'-',1)::int*12 + split_part(c.exp,'-',2)::int)
             - (extract(year from now())::int*12 + extract(month from now())::int) > 3)))::int as my_certs_current,
      (select count(*) from certs c where c.department_id = d.id and c.member_id = me.my_mid
           and public.valid_exp_ym(c.exp)
           and not public.cert_never_expires(c.no_expiry, c.cert_type_id, c.department_id)
           and (split_part(c.exp,'-',1)::int*12 + split_part(c.exp,'-',2)::int)
             - (extract(year from now())::int*12 + extract(month from now())::int) between 0 and 3)::int as my_certs_expiring,
      (select count(*) from certs c where c.department_id = d.id and c.member_id = me.my_mid
           and public.valid_exp_ym(c.exp)
           and not public.cert_never_expires(c.no_expiry, c.cert_type_id, c.department_id)
           and (split_part(c.exp,'-',1)::int*12 + split_part(c.exp,'-',2)::int)
             - (extract(year from now())::int*12 + extract(month from now())::int) < 0)::int as my_certs_expired,

      -- DUTIES assigned to me here. Two numbers, because the card needs both:
      -- open drives the "N due" stat, overdue drives the red edge.
      (select count(*) from duties du where du.department_id = d.id
                                       and du.assigned_to = me.my_mid and du.done = false)::int as my_open_duties,
      (select count(*) from duties du where du.department_id = d.id
                                       and du.assigned_to = me.my_mid and du.done = false
                                       and du.due_date is not null and du.due_date < current_date)::int as my_overdue_duties,

      -- NEXT EVENT across the same four calendar sources MemberDashboard reads.
      -- Audience-aware: a non-leader is not told about a leadership-only drill
      -- they cannot attend. content_calendar's text column is `caption`, not
      -- `title` — confirmed against the live schema, not assumed.
      nx.nd as my_next_event_date, nx.nt as my_next_event_title, nx.nk as my_next_event_type

    from departments d
    -- The caller's own member row AT THIS DEPARTMENT. Phase 1b's unique index on
    -- (lower(email), department_id) guarantees at most one, so this cannot fan out;
    -- the limit 1 is belt and braces.
    left join lateral (
      select m.id as my_mid, m.access as my_access
        from members m
       where m.email is not null
         and lower(m.email) = lower(auth.email())
         and m.status in ('Active','Probationary')
         and m.department_id = d.id
       limit 1
    ) me on true
    left join lateral (
      select x.d as nd, x.t as nt, x.k as nk
        from (
          select ts.date as d, ts.title as t, 'Training'::text as k
            from training_sessions ts
           where ts.department_id = d.id and ts.date >= current_date and coalesce(ts.status, 'scheduled') <> 'cancelled'
             and (coalesce(me.my_access && array['Project Admin','Department Admin','Board Member','Officer']::text[], false)
                  or coalesce(ts.audience,'everyone') not in ('leadership','board'))
          union all
          select fe.date, fe.title, 'Funding'::text
            from funding_events fe where fe.department_id = d.id and fe.date >= current_date
          union all
          select re.date, re.title, 'Recruitment'::text
            from recruitment_events re where re.department_id = d.id and re.date >= current_date
          union all
          select cc.date, cc.caption, 'Content'::text
            from content_calendar cc where cc.department_id = d.id and cc.date >= current_date
        ) x
       order by x.d asc, x.k asc
       limit 1
    ) nx on true
    -- UNCHANGED FROM PHASE 2 — the authorization boundary, verbatim.
    where d.id in (
      select m.department_id from public.members m
      where lower(m.email) = lower(auth.email())
        and m.status in ('Active','Probationary')
    )
  )
  select
    b.department_id, b.department_name, b.station, b.city,
    b.can_manage,
    -- EVERY leadership column is gated on can_manage. This is the whole point of
    -- the migration: a non-managing member gets NULL over the wire, not a number
    -- the client is trusted to hide.
    case when b.can_manage then b.admin_name  end,
    case when b.can_manage then b.admin_email end,
    case when b.can_manage then
      case when b.last_activity is null then 'RED'
           when current_date - b.last_activity::date < 14 then 'GREEN'
           when current_date - b.last_activity::date <= 30 then 'YELLOW'
           else 'RED' end
    end as health,
    case when b.can_manage then b.last_activity end,
    case when b.can_manage then
      case when b.last_activity is null then null else current_date - b.last_activity::date end
    end as days_since_activity,
    case when b.can_manage then b.active_members_30d      end,
    case when b.can_manage then b.member_count            end,
    case when b.can_manage then b.documents_count         end,
    case when b.can_manage then b.apparatus_count         end,
    case when b.can_manage then b.training_sessions_count end,
    case when b.can_manage then b.profile_complete        end,
    case when b.can_manage then b.members_no_email_count  end,
    case when b.can_manage then b.documents_no_text_count end,
    case when b.can_manage then b.expiring_certs_count    end,
    case when b.can_manage then b.expired_certs_count     end,
    case when b.can_manage then b.overdue_duties_count    end,
    case when b.can_manage then b.open_action_items_count end,
    -- Member-scoped: always returned, always the caller's own data.
    -- pct is NULL when the month held no qualifying drills — "no drills yet" and
    -- "attended none of them" are different facts and must not both read as 0%.
    case when b.my_attendance_total > 0
         then round(b.my_attendance_attended * 100.0 / b.my_attendance_total)::int end as my_attendance_pct,
    b.my_attendance_total, b.my_attendance_attended,
    b.my_certs_current, b.my_certs_expiring, b.my_certs_expired,
    b.my_open_duties, b.my_overdue_duties,
    b.my_next_event_date, b.my_next_event_title, b.my_next_event_type
  from base b
  order by
    case when b.last_activity is null then 0
         when current_date - b.last_activity::date > 30 then 0
         when current_date - b.last_activity::date >= 14 then 1 else 2 end,
    b.last_activity asc nulls first, b.department_name asc;
end;
$function$
$r9$;


  -- =================================================================
  -- 7. HOUSEKEEPING (R8).
  -- =================================================================
  EXECUTE 'REVOKE ALL ON FUNCTION public.swap_week_dates(uuid, uuid) FROM PUBLIC, anon, authenticated';
  EXECUTE 'REVOKE ALL ON FUNCTION public.move_week(uuid, text) FROM PUBLIC, anon, authenticated';
  EXECUTE 'DROP FUNCTION public.swap_week_dates(uuid, uuid)';
  EXECUTE 'DROP FUNCTION public.move_week(uuid, text)';

  -- =================================================================
  -- 8. PRIVILEGES.
  -- =================================================================
  FOREACH k IN ARRAY v_rpcs LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon', k);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', k);
  END LOOP;
  -- (the guard keeps its Slice 6 ACL: CREATE OR REPLACE preserves it — re-asserted below)

  -- =================================================================
  -- 9. POST-CONDITIONS — any miss rolls the whole thing back.
  -- =================================================================
  FOR k, v IN SELECT * FROM jsonb_each_text(v_pin_unchanged) LOOP
    IF md5(pg_get_functiondef(to_regprocedure(k))) <> v THEN RAISE EXCEPTION 'POST: % changed — it must not.', k; END IF;
  END LOOP;
  IF position(v_ins_r1 in pg_get_functiondef(to_regprocedure('public.open_signin(uuid)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.open_signin(uuid)')), v_ins_r1, '')) <> '38d66e034a5f0d8a71b9e668e358c446' THEN
    RAISE EXCEPTION 'POST: public.open_signin(uuid) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r2 in pg_get_functiondef(to_regprocedure('public.current_signin_token(uuid)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.current_signin_token(uuid)')), v_ins_r2, '')) <> '25970cb998c1f6bf53a56e4da84a57f2' THEN
    RAISE EXCEPTION 'POST: public.current_signin_token(uuid) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r3 in pg_get_functiondef(to_regprocedure('public.member_check_in(uuid,text,double precision,double precision,double precision)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.member_check_in(uuid,text,double precision,double precision,double precision)')), v_ins_r3, '')) <> '089a9b4c37c911e632375294985ad150' THEN
    RAISE EXCEPTION 'POST: public.member_check_in(uuid,text,double precision,double precision,double precision) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r4 in pg_get_functiondef(to_regprocedure('public.set_session_location(uuid,double precision,double precision,integer,text)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.set_session_location(uuid,double precision,double precision,integer,text)')), v_ins_r4, '')) <> '73122c636c37a2017070804b737b374e' THEN
    RAISE EXCEPTION 'POST: public.set_session_location(uuid,double precision,double precision,integer,text) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r5 in pg_get_functiondef(to_regprocedure('public.set_my_session_registration(uuid,text)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.set_my_session_registration(uuid,text)')), v_ins_r5, '')) <> 'f3c7c3e7b41069adddf5cb95e8b10489' THEN
    RAISE EXCEPTION 'POST: public.set_my_session_registration(uuid,text) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r6 in pg_get_functiondef(to_regprocedure('public.finalize_training_session(uuid,integer)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.finalize_training_session(uuid,integer)')), v_ins_r6, '')) <> '6a0f50df0c2e82a3f3f61eda3fe4d129' THEN
    RAISE EXCEPTION 'POST: public.finalize_training_session(uuid,integer) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r7 in pg_get_functiondef(to_regprocedure('public.correct_training_session(uuid,jsonb,uuid[],uuid[],text)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.correct_training_session(uuid,jsonb,uuid[],uuid[],text)')), v_ins_r7, '')) <> 'c243fcc63206169f810be3ff2db895ce' THEN
    RAISE EXCEPTION 'POST: public.correct_training_session(uuid,jsonb,uuid[],uuid[],text) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r8 in pg_get_functiondef(to_regprocedure('public.attach_drill_plan_to_session(uuid,uuid)'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.attach_drill_plan_to_session(uuid,uuid)')), v_ins_r8, '')) <> '62590b6a9006b28cd009f70e6a11327d' THEN
    RAISE EXCEPTION 'POST: public.attach_drill_plan_to_session(uuid,uuid) is not exactly the live body + its slice7 block.';
  END IF;
  IF position(v_ins_r9 in pg_get_functiondef(to_regprocedure('public.my_department_rollup()'))) = 0
     OR md5(replace(pg_get_functiondef(to_regprocedure('public.my_department_rollup()')), v_ins_r9, '')) <> 'cd368f0fca832bbb0e804c939a7a9d10' THEN
    RAISE EXCEPTION 'POST: public.my_department_rollup() is not exactly the live body + its slice7 block.';
  END IF;
  IF to_regprocedure('public.swap_week_dates(uuid,uuid)') IS NOT NULL OR to_regprocedure('public.move_week(uuid,text)') IS NOT NULL THEN
    RAISE EXCEPTION 'POST: swap_week_dates / move_week still exist.';
  END IF;
  IF position('STATUS_LOCKED' in pg_get_functiondef(to_regprocedure(v_guard_sig))) = 0
     OR has_function_privilege('anon', v_guard_sig, 'EXECUTE') OR has_function_privilege('authenticated', v_guard_sig, 'EXECUTE')
     OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.training_sessions'::regclass AND tgname = 'training_session_lock_guard'
                      AND pg_get_triggerdef(oid) LIKE '%BEFORE INSERT OR UPDATE ON public.training_sessions%') THEN
    RAISE EXCEPTION 'POST: the lock guard / its trigger is not as intended.';
  END IF;
  FOREACH k IN ARRAY v_rpcs LOOP
    IF has_function_privilege('anon', k, 'EXECUTE') OR NOT has_function_privilege('authenticated', k, 'EXECUTE')
       OR NOT (SELECT prosecdef AND proconfig @> array['search_path=public'] FROM pg_proc WHERE oid = to_regprocedure(k)) THEN
      RAISE EXCEPTION 'POST: % privileges / definer / search_path wrong.', k;
    END IF;
  END LOOP;
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.training_session_requests'::regclass)
     OR (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'training_session_requests') <> 1
     OR has_table_privilege('authenticated', 'public.training_session_requests', 'INSERT')
     OR has_table_privilege('authenticated', 'public.training_session_requests', 'UPDATE')
     OR has_table_privilege('authenticated', 'public.training_session_requests', 'DELETE')
     OR has_table_privilege('anon', 'public.training_session_requests', 'SELECT')
     OR has_column_privilege('authenticated', 'public.training_session_requests', 'initiator_signature', 'SELECT')
     OR has_column_privilege('authenticated', 'public.training_session_requests', 'approver_signature', 'SELECT')
     OR NOT has_column_privilege('authenticated', 'public.training_session_requests', 'reason', 'SELECT') THEN
    RAISE EXCEPTION 'POST: training_session_requests RLS / grants wrong (signatures must not be selectable).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.training_session_audit'::regclass AND conname = 'training_session_audit_action_check'
                   AND pg_get_constraintdef(oid) LIKE '%cancel%' AND pg_get_constraintdef(oid) LIKE '%restore%' AND pg_get_constraintdef(oid) LIKE '%finalize%') THEN
    RAISE EXCEPTION 'POST: the audit action CHECK does not carry cancel/restore.';
  END IF;
  FOR k, v IN SELECT * FROM jsonb_each_text(v_ts_policies) LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'training_sessions'
                     AND policyname = split_part(k, '|', 1) AND coalesce(qual, '') = split_part(v, '|', 1) AND coalesce(with_check, '') = split_part(v, '|', 2)) THEN
      RAISE EXCEPTION 'POST: training_sessions policy "%" changed — it must not.', split_part(k, '|', 1);
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.training_sessions WHERE status IS DISTINCT FROM 'scheduled') THEN
    RAISE EXCEPTION 'POST: an existing session is not scheduled after the column add.';
  END IF;

  PERFORM pg_notify('pgrst', 'reload schema');
END
$mig$;

-- ---------------------------------------------------------------------
-- STATE ROW (read-only) — paste this back with the apply.
-- ---------------------------------------------------------------------
SELECT jsonb_build_object(
  'status_column',      (SELECT column_default || ' / ' || is_nullable FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_sessions' AND column_name = 'status'),
  'sessions_by_status', (SELECT jsonb_object_agg(status, n) FROM (SELECT status, count(*) n FROM public.training_sessions GROUP BY 1) x),
  'requests_table',     to_regclass('public.training_session_requests') IS NOT NULL,
  'requests_rows',      (SELECT count(*) FROM public.training_session_requests),
  'audit_action_check', (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.training_session_audit'::regclass AND conname = 'training_session_audit_action_check'),
  'guard_trigger',      (SELECT pg_get_triggerdef(oid) LIKE '%BEFORE INSERT OR UPDATE%' FROM pg_trigger WHERE tgrelid = 'public.training_sessions'::regclass AND tgname = 'training_session_lock_guard'),
  'rpcs',               (SELECT jsonb_agg(p.proname || ' anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' auth=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') ORDER BY p.proname)
                           FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
                            AND p.proname IN ('request_session_change', 'approve_session_change', 'reject_session_change', 'withdraw_session_change', 'session_change_signatures')),
  'dropped',            to_regproc('public.swap_week_dates') IS NULL AND to_regproc('public.move_week') IS NULL,
  'verified_presence',  (SELECT count(*) FROM public.station_presence WHERE verified),
  'attested_md5',       md5(pg_get_functiondef('public.attested_training(uuid,timestamptz,timestamptz)'::regprocedure))
) AS slice7_db_state;
